48	/**
49	 * This JAX-RS resource is decorating the Admin Realm API in order to support specific behaviors from the
50	 * administration console.
51	 *
52	 * Its use is restricted to the built-in administration console.
53	 */
54	public class UIRealmResource {
55	
56	    private final RealmAdminResource delegate;
57	    private final KeycloakSession session;
58	    private final AdminPermissionEvaluator auth;
59	    private final AdminEventBuilder adminEvent;
60	
61	    public UIRealmResource(KeycloakSession session, AdminPermissionEvaluator auth, AdminEventBuilder adminEvent) {
62	        this.session = session;
63	        this.auth = auth;
64	        this.adminEvent = adminEvent;
65	        this.delegate = new RealmAdminResource(session, auth, adminEvent);
66	    }
67	
68	    @PUT
69	    @Consumes(MediaType.APPLICATION_JSON)
70	    @Operation( hidden = true )
71	    public Response updateRealm(UIRealmRepresentation rep) {
72	        Response response = delegate.updateRealm(rep);
73	
74	        if (isSuccessful(response)) {
75	            updateUserProfileConfiguration(rep);
76	        }
77	
78	        return response;
79	    }
80	
81	    @GET
82	    @Path("info")
83	    @Operation(summary = "Gets information about the realm, viewable by all realm admins")
84	    @APIResponse(responseCode = "200", description = "", content = {
85	            @Content(schema = @Schema(implementation = UIRealmInfo.class, type = SchemaType.OBJECT))})
86	    @Produces(MediaType.APPLICATION_JSON)
87	    public UIRealmInfo getInfo() {
88	        auth.requireAnyAdminRole();
89	
90	        final var info = new UIRealmInfo();
91	        info.setUserProfileProvidersEnabled(isAtLeastOneUserStorageProviderEnabled());
92	        return info;
93	    }
94	
95	    private boolean isAtLeastOneUserStorageProviderEnabled() {
96	        return ((StorageProviderRealmModel) session.getContext().getRealm()).getUserStorageProvidersStream()
97	                .anyMatch(UserStorageProviderModel::isEnabled);
98	    }
99	
100	    private void updateUserProfileConfiguration(UIRealmRepresentation rep) {
101	        UserProfileResource userProfileResource = new UserProfileResource(session, auth, adminEvent);
102	        UPConfig config = rep.getUpConfig();
103	        if (config == null) {
104	            return;
105	        }
106	        userProfileResource.setAndGetConfiguration(config);
107	    }
108	
109	    private boolean isSuccessful(Response response) {
110	        return Family.SUCCESSFUL.equals(response.getStatusInfo().getFamily());
111	    }
112	}
